
'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import {
  ArrowLeft,
  BookOpen,
  CheckCircle2,
  ChevronDown,
  FileText,
  GraduationCap,
  Lightbulb,
  Loader2,
  Printer,
  Search,
  Target,
  Users,
  UserRound,
  Wrench,
  LayoutDashboard,
  ExternalLink,
  CircleHelp,
} from 'lucide-react';

type AnyObject = Record<string, unknown>;

type DashboardData = {
  email: string;
  interests: unknown;
  goals: unknown;
  skills: unknown;
  mode: string;
  groupMembers: unknown[];
  papers: unknown[];
  gaps: unknown[];
  ideas: unknown[];
  selectedProject: AnyObject | null;
  faculty: unknown[];
  recommendationData: unknown;
  profileData: unknown;
};

const EMPTY_DATA: DashboardData = {
  email: '',
  interests: '',
  goals: '',
  skills: '',
  mode: '',
  groupMembers: [],
  papers: [],
  gaps: [],
  ideas: [],
  selectedProject: null,
  faculty: [],
  recommendationData: null,
  profileData: null,
};

function parseJSON(value: string | null): unknown {
  if (!value) return null;

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

function text(value: unknown): string {
  if (value === null || value === undefined) return '';

  if (
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    return String(value).trim();
  }

  if (Array.isArray(value)) {
    return value.map(text).filter(Boolean).join(', ');
  }

  if (typeof value === 'object') {
    const obj = value as AnyObject;

    for (const key of [
      'description',
      'text',
      'name',
      'title',
      'value',
      'email',
    ]) {
      if (obj[key] !== undefined) {
        const result = text(obj[key]);
        if (result) return result;
      }
    }
  }

  return '';
}

function asObject(value: unknown): AnyObject | null {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value as AnyObject;
  }

  return null;
}

function asArray(value: unknown): unknown[] {
  if (Array.isArray(value)) return value;

  if (typeof value === 'string' && value.trim()) {
    return value
      .split(/[,;\n]/)
      .map((item) => item.trim())
      .filter(Boolean);
  }

  return [];
}

function firstValue(
  sources: unknown[],
  keys: string[],
): unknown {
  for (const source of sources) {
    const obj = asObject(source);
    if (!obj) continue;

    for (const key of keys) {
      const value = obj[key];

      if (
        value !== undefined &&
        value !== null &&
        value !== ''
      ) {
        return value;
      }
    }
  }

  return '';
}

function findArrays(
  value: unknown,
  possibleKeys: string[],
  depth = 0,
): unknown[][] {
  if (depth > 7 || !value || typeof value !== 'object') {
    return [];
  }

  const found: unknown[][] = [];

  if (Array.isArray(value)) {
    for (const item of value) {
      found.push(
        ...findArrays(item, possibleKeys, depth + 1),
      );
    }

    return found;
  }

  const obj = value as AnyObject;

  for (const key of possibleKeys) {
    if (Array.isArray(obj[key]) && (obj[key] as unknown[]).length) {
      found.push(obj[key] as unknown[]);
    }
  }

  for (const child of Object.values(obj)) {
    if (child && typeof child === 'object') {
      found.push(...findArrays(child, possibleKeys, depth + 1));
    }
  }

  return found;
}

function findBestArray(
  value: unknown,
  keys: string[],
): unknown[] {
  const arrays = findArrays(value, keys);

  if (!arrays.length) return [];

  return arrays.reduce(
    (best, current) =>
      current.length > best.length ? current : best,
    [] as unknown[],
  );
}

function collectStoredValues(
  storage: Storage,
  keyNames: string[],
): unknown[] {
  const results: unknown[] = [];

  for (const key of keyNames) {
    const value = parseJSON(storage.getItem(key));

    if (value !== null && value !== '') {
      results.push(value);
    }
  }

  return results;
}

function collectMatchingStorage(
  storage: Storage,
  prefixes: string[],
): unknown[] {
  const results: unknown[] = [];

  for (let index = 0; index < storage.length; index++) {
    const key = storage.key(index);

    if (!key || !prefixes.some((prefix) => key.startsWith(prefix))) {
      continue;
    }

    const value = parseJSON(storage.getItem(key));

    if (value !== null) {
      results.push(value);
    }
  }

  return results;
}

function renderValue(value: unknown): string {
  if (value === null || value === undefined || value === '') {
    return 'Not available';
  }

  if (typeof value === 'string' || typeof value === 'number') {
    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'Yes' : 'No';
  }

  return JSON.stringify(value, null, 2);
}

function displayFieldName(key: string): string {
  return key
    .replace(/_/g, ' ')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function getTitle(value: unknown, fallback: string): string {
  const obj = asObject(value);

  if (!obj) return text(value) || fallback;

  return (
    text(obj.title) ||
    text(obj.name) ||
    text(obj.project_title) ||
    text(obj.paper_title) ||
    fallback
  );
}

function getPaperAuthors(paper: unknown): string {
  const obj = asObject(paper);
  if (!obj) return '';

  return text(obj.authors ?? obj.author_names ?? obj.author);
}

function getPaperUrl(paper: unknown): string {
  const obj = asObject(paper);

  return (
    text(obj.url) ||
    text(obj.doi_url) ||
    text(obj.paper_url) ||
    text(obj.link)
  );
}

function getFacultyName(member: unknown): string {
  const obj = asObject(member);

  if (!obj) return text(member) || 'Faculty member';

  return (
    text(obj.name) ||
    text(obj.faculty_name) ||
    text(obj.full_name) ||
    'Faculty member'
  );
}

function Section({
  id,
  number,
  title,
  description,
  icon,
  children,
}: {
  id: string;
  number: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <section
      id={id}
      className="scroll-mt-24 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"
    >
      <div className="border-b border-slate-100 px-5 py-5 sm:px-7">
        <div className="flex items-start gap-3">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-blue-50 text-blue-700">
            {icon}
          </div>

          <div className="min-w-0">
            <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-400">
              Section {number}
            </p>

            <h2 className="mt-1 text-lg font-bold text-slate-950">
              {title}
            </h2>

            <p className="mt-1 text-sm leading-6 text-slate-500">
              {description}
            </p>
          </div>
        </div>
      </div>

      <div className="p-5 sm:p-7">{children}</div>
    </section>
  );
}

function EmptyState({ message }: { message: string }) {
  return (
    <div className="rounded-xl border border-dashed border-slate-200 bg-slate-50/70 px-5 py-8 text-center">
      <CircleHelp className="mx-auto h-6 w-6 text-slate-400" />

      <p className="mt-3 text-sm font-medium text-slate-700">
        No saved information found
      </p>

      <p className="mx-auto mt-1 max-w-lg text-xs leading-6 text-slate-500">
        {message}
      </p>
    </div>
  );
}

function ValueBlock({
  label,
  value,
}: {
  label: string;
  value: unknown;
}) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  return (
    <div className="rounded-xl border border-slate-100 bg-slate-50/70 p-4">
      <p className="text-[10px] font-bold uppercase tracking-[0.12em] text-slate-500">
        {label}
      </p>

      <p className="mt-2 whitespace-pre-wrap break-words text-sm leading-7 text-slate-800">
        {renderValue(value)}
      </p>
    </div>
  );
}

function DataCard({
  item,
  index,
  kind,
}: {
  item: unknown;
  index: number;
  kind: 'paper' | 'gap' | 'idea';
}) {
  const obj = asObject(item);
  const title =
    getTitle(
      item,
      kind === 'paper'
        ? `Research paper ${index + 1}`
        : kind === 'gap'
          ? `Research gap ${index + 1}`
          : `Project idea ${index + 1}`,
    );

  const url = kind === 'paper' ? getPaperUrl(item) : '';

  const fields = obj
    ? Object.entries(obj).filter(
        ([key, value]) =>
          value !== null &&
          value !== undefined &&
          value !== '' &&
          ![
            'id',
            'paper_id',
            'work_id',
            'idea_id',
            'gap_id',
            'title',
            'name',
            'url',
            'paper_url',
            'doi_url',
            'authors',
            'author',
          ].includes(key),
      )
    : [];

  return (
    <details className="group rounded-xl border border-slate-200 bg-white">
      <summary className="flex cursor-pointer list-none items-start gap-3 p-4">
        <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-slate-100 text-xs font-bold text-slate-700">
          {index + 1}
        </span>

        <div className="min-w-0 flex-1">
          <h3 className="text-sm font-semibold leading-6 text-slate-900">
            {title}
          </h3>

          {kind === 'paper' && getPaperAuthors(item) && (
            <p className="mt-1 text-xs leading-5 text-slate-500">
              {getPaperAuthors(item)}
            </p>
          )}

          {obj && (
            <p className="mt-1 text-xs text-slate-400">
              Open for full details
            </p>
          )}
        </div>

        <ChevronDown className="mt-1 h-4 w-4 shrink-0 text-slate-400 transition group-open:rotate-180" />
      </summary>

      <div className="space-y-3 border-t border-slate-100 p-4">
        {url && (
          <a
            href={url}
            target="_blank"
            rel="noreferrer"
            className="inline-flex items-center gap-2 text-xs font-semibold text-blue-700 hover:text-blue-900"
          >
            Open paper <ExternalLink className="h-3.5 w-3.5" />
          </a>
        )}

        {fields.length > 0 ? (
          fields.map(([key, value]) => (
            <ValueBlock
              key={key}
              label={displayFieldName(key)}
              value={value}
            />
          ))
        ) : (
          <p className="whitespace-pre-wrap break-words text-sm leading-6 text-slate-600">
            {renderValue(item)}
          </p>
        )}
      </div>
    </details>
  );
}

function FacultyCard({
  member,
  index,
}: {
  member: unknown;
  index: number;
}) {
  const obj = asObject(member);

  const name = getFacultyName(member);
  const department = text(obj?.department);
  const designation = text(obj?.designation);
  const expertise =
    obj?.research_areas ??
    obj?.areas_of_expertise ??
    obj?.expertise;

  const explanation =
    text(obj?.match_reason) ||
    text(obj?.explanation) ||
    text(obj?.reason);

  const score =
    obj?.match_score ??
    obj?.relevance_score ??
    obj?.score;

  const publications = asArray(
    obj?.publications ?? obj?.papers,
  );

  return (
    <article className="rounded-xl border border-slate-200 p-5">
      <div className="flex items-start gap-3">
        <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-slate-900 text-sm font-bold text-white">
          #{index + 1}
        </div>

        <div className="min-w-0 flex-1">
          <h3 className="font-bold text-slate-950">{name}</h3>

          {(designation || department) && (
            <p className="mt-1 text-xs leading-5 text-slate-500">
              {[designation, department].filter(Boolean).join(' · ')}
            </p>
          )}

          {score !== undefined && score !== null && score !== '' && (
            <p className="mt-2 inline-flex rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-800">
              Match score: {String(score)}
            </p>
          )}
        </div>
      </div>

      {explanation && (
        <div className="mt-4 rounded-lg bg-slate-50 p-3">
          <p className="text-[10px] font-bold uppercase tracking-wide text-slate-500">
            Match explanation
          </p>
          <p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-700">
            {explanation}
          </p>
        </div>
      )}

      {expertise !== undefined && expertise !== null && (
        <ValueBlock label="Research expertise" value={expertise} />
      )}

      {text(obj?.email) && (
        <a
          href={`mailto:${text(obj?.email)}`}
          className="mt-4 inline-flex items-center gap-2 text-xs font-semibold text-blue-700 hover:text-blue-900"
        >
          Contact faculty <ExternalLink className="h-3 w-3" />
        </a>
      )}

      {publications.length > 0 && (
        <details className="mt-4 rounded-lg border border-slate-100 p-3">
          <summary className="cursor-pointer text-xs font-semibold text-slate-700">
            Relevant publications ({publications.length})
          </summary>

          <ul className="mt-3 space-y-2">
            {publications.map((publication, publicationIndex) => (
              <li
                key={`${text(publication)}-${publicationIndex}`}
                className="text-xs leading-6 text-slate-600"
              >
                {text(publication) || renderValue(publication)}
              </li>
            ))}
          </ul>
        </details>
      )}
    </article>
  );
}

function loadDashboardData(): DashboardData {
  const local = window.localStorage;
  const session = window.sessionStorage;

  const profileSources = [
    ...collectStoredValues(local, [
      'userProfile',
      'profile',
      'account',
      'user',
      'researchPilotProfile',
    ]),
    ...collectStoredValues(session, [
      'userProfile',
      'profile',
      'account',
      'researchPilotProfile',
    ]),
  ];

  const recommendationCaches = [
    ...collectMatchingStorage(local, [
      'researchpilot:recommendations:v1:',
      'researchpilot:last-recommendations:',
    ]),
    ...collectMatchingStorage(session, [
      'researchpilot:recommendations:v1:',
      'researchpilot:last-recommendations:',
    ]),
  ];

  const gapSources = [
    ...collectStoredValues(session, [
      'researchGaps',
      'researchGapPapers',
      'researchGapTopics',
    ]),
    ...collectMatchingStorage(local, [
      'researchpilot:research-gaps:v1:',
    ]),
  ];

  const ideaSources = [
    ...collectStoredValues(session, [
      'projectIdeas',
      'selectedProjectIdea',
      'researchPilotSelectedProject',
    ]),
  ];

  const currentProject = asObject(
    parseJSON(
      session.getItem('researchPilotDashboardProject'),
    ) ??
      parseJSON(session.getItem('selectedProjectIdea')) ??
      parseJSON(session.getItem('researchPilotSelectedProject')),
  );

  const projectContext =
    parseJSON(
      session.getItem('researchPilotDashboardContext'),
    ) ??
    parseJSON(session.getItem('selectedProjectContext')) ??
    parseJSON(session.getItem('researchPilotProjectContext'));

  const facultyValue = parseJSON(
    session.getItem('researchPilotDashboardFaculty'),
  );

  const faculty = Array.isArray(facultyValue) ? facultyValue : [];

  const allSources = [
    ...profileSources,
    ...recommendationCaches,
    ...gapSources,
    ...ideaSources,
    projectContext,
    currentProject,
  ];

  const email =
    text(local.getItem('userEmail')) ||
    text(local.getItem('email')) ||
    text(session.getItem('researchGapEmail')) ||
    text(firstValue(allSources, ['email', 'user_email']));

  const interests =
    firstValue(allSources, [
      'interests',
      'research_interests',
      'researchInterests',
      'areas_of_interest',
    ]) ||
    session.getItem('researchInterests') ||
    session.getItem('interests') ||
    local.getItem('researchInterests') ||
    '';

  const goals =
    firstValue(allSources, [
      'goals',
      'research_goals',
      'researchGoals',
      'userGoals',
    ]) ||
    session.getItem('researchGoals') ||
    session.getItem('userGoals') ||
    local.getItem('researchGoals') ||
    '';

  const skills =
    firstValue(allSources, [
      'skills',
      'research_skills',
      'researchSkills',
      'userSkills',
    ]) ||
    session.getItem('researchSkills') ||
    session.getItem('userSkills') ||
    local.getItem('researchSkills') ||
    '';

  const recommendationData =
    recommendationCaches.length > 0
      ? recommendationCaches[recommendationCaches.length - 1]
      : null;

  const modeValue = text(
    firstValue(
      [
        recommendationData,
        ...recommendationCaches,
        projectContext,
        ...profileSources,
      ],
      [
        'mode',
        'recommendation_type',
        'recommendationType',
        'recommendation_mode',
        'type',
        'group_mode',
      ],
    ),
  );

  const mode =
    /group|team/i.test(modeValue) ||
    modeValue === 'true'
      ? 'Group recommendation'
      : /individual|single|personal/i.test(modeValue)
        ? 'Individual recommendation'
        : modeValue || 'Not recorded';

  const groupMembers = findBestArray(
    recommendationCaches,
    [
      'group_members',
      'groupMembers',
      'members',
      'students',
      'team_members',
      'teamMembers',
    ],
  );

  const papers = findBestArray(
    [
      recommendationCaches,
      ...recommendationCaches,
      ...gapSources,
      currentProject,
      projectContext,
    ],
    [
      'papers',
      'recommended_papers',
      'recommendedPapers',
      'recommendations',
      'works',
      'results',
      'items',
    ],
  );

  const gaps = findBestArray(
    gapSources,
    [
      'research_gaps',
      'researchGaps',
      'gaps',
      'identified_gaps',
      'identifiedGaps',
      'results',
    ],
  );

  const ideas = findBestArray(
    ideaSources,
    [
      'project_ideas',
      'projectIdeas',
      'ideas',
      'results',
      'items',
    ],
  );

  const filteredIdeas = ideas.filter((item) => {
    const obj = asObject(item);

    // Do not count the selected project as an additional generated idea.
    return !(
      currentProject &&
      obj &&
      text(obj.idea_id) &&
      text(obj.idea_id) === text(currentProject.idea_id)
    );
  });

  return {
    email,
    interests,
    goals,
    skills,
    mode,
    groupMembers,
    papers,
    gaps,
    ideas: filteredIdeas,
    selectedProject: currentProject,
    faculty,
    recommendationData,
    profileData: profileSources[0] ?? null,
  };
}

export default function FinalDashboardPage() {
  const [data, setData] = useState<DashboardData>(EMPTY_DATA);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    try {
      setData(loadDashboardData());
    } catch (error) {
      console.error('Could not load the research dashboard:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  const project = data.selectedProject;

  const stats = [
    {
      label: 'Recommended papers',
      value: data.papers.length,
      icon: <BookOpen className="h-5 w-5" />,
    },
    {
      label: 'Research gaps',
      value: data.gaps.length,
      icon: <Search className="h-5 w-5" />,
    },
    {
      label: 'Project ideas',
      value: data.ideas.length,
      icon: <Lightbulb className="h-5 w-5" />,
    },
    {
      label: 'Faculty matches',
      value: data.faculty.length,
      icon: <GraduationCap className="h-5 w-5" />,
    },
  ];

  if (loading) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-[#f7f9fc]">
        <div className="text-center">
          <Loader2 className="mx-auto h-8 w-8 animate-spin text-blue-700" />
          <p className="mt-4 text-sm text-slate-600">
            Preparing your research dashboard…
          </p>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-[#f7f9fc] text-slate-900">
      <header className="sticky top-0 z-30 border-b border-slate-200/80 bg-white/95 backdrop-blur-xl print:static">
        <div className="mx-auto flex h-[68px] max-w-7xl items-center justify-between px-5 sm:px-8">
          <Link
            href="/project-ideas"
            className="inline-flex items-center gap-2 text-sm font-medium text-slate-600 hover:text-slate-950"
          >
            <ArrowLeft className="h-4 w-4" />
            <span className="hidden sm:inline">Project Ideas</span>
          </Link>

          <Link
            href="/"
            className="text-sm font-bold tracking-[0.16em] text-slate-950"
          >
            RESEARCHPILOT
          </Link>

          <button
            type="button"
            onClick={() => window.print()}
            className="inline-flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700 transition hover:bg-slate-50"
          >
            <Printer className="h-4 w-4" />
            <span className="hidden sm:inline">Print / Save PDF</span>
          </button>
        </div>
      </header>

      <div className="mx-auto max-w-7xl px-5 pb-20 pt-8 sm:px-8">
        <div className="mb-8 overflow-hidden rounded-3xl bg-slate-950 text-white shadow-lg">
          <div className="relative px-6 py-9 sm:px-10 sm:py-12">
            <div className="pointer-events-none absolute -right-10 -top-20 h-64 w-64 rounded-full bg-blue-600/30 blur-3xl" />
            <div className="pointer-events-none absolute bottom-0 right-1/3 h-40 w-40 rounded-full bg-violet-500/20 blur-3xl" />

            <div className="relative">
              <div className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/10 px-3 py-1.5 text-[10px] font-semibold uppercase tracking-[0.16em] text-blue-100">
                <LayoutDashboard className="h-3.5 w-3.5" />
                Research journey overview
              </div>

              <h1 className="mt-5 max-w-3xl text-3xl font-bold tracking-tight sm:text-5xl">
                Your research,
                <span className="block text-blue-300">
                  all in one place.
                </span>
              </h1>

              <p className="mt-4 max-w-2xl text-sm leading-7 text-slate-300 sm:text-base">
                A consolidated overview of your profile, literature
                recommendations, research gaps, project directions,
                selected project, and faculty expertise alignment.
              </p>

              <div className="mt-6 flex flex-wrap gap-2">
                <span className="rounded-full border border-white/15 bg-white/10 px-3 py-1.5 text-xs text-slate-200">
                  {data.mode}
                </span>

                {data.email && (
                  <span className="rounded-full border border-white/15 bg-white/10 px-3 py-1.5 text-xs text-slate-200">
                    {data.email}
                  </span>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="mb-8 grid grid-cols-2 gap-3 lg:grid-cols-4">
          {stats.map((stat) => (
            <div
              key={stat.label}
              className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5"
            >
              <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-50 text-blue-700">
                {stat.icon}
              </div>

              <p className="mt-4 text-2xl font-bold tracking-tight text-slate-950">
                {stat.value}
              </p>

              <p className="mt-1 text-xs leading-5 text-slate-500">
                {stat.label}
              </p>
            </div>
          ))}
        </div>

        <div className="mb-8 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5">
          <p className="mb-3 text-xs font-bold uppercase tracking-[0.14em] text-slate-500">
            Jump to section
          </p>

          <div className="flex flex-wrap gap-2">
            {[
              ['profile', 'Profile'],
              ['papers', 'Research papers'],
              ['gaps', 'Research gaps'],
              ['ideas', 'Project ideas'],
              ['selected-project', 'Selected project'],
              ['faculty', 'Faculty matches'],
            ].map(([id, label]) => (
              <a
                key={id}
                href={`#${id}`}
                className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-medium text-slate-600 transition hover:border-blue-200 hover:bg-blue-50 hover:text-blue-800"
              >
                {label}
              </a>
            ))}
          </div>
        </div>

        <div className="space-y-6">
          <Section
            id="profile"
            number="01"
            title="Your research profile"
            description="The interests, goals, skills, and recommendation mode that guide your research journey."
            icon={<UserRound className="h-5 w-5" />}
          >
            <div className="grid gap-4 sm:grid-cols-2">
              <ValueBlock label="Account email" value={data.email} />
              <ValueBlock label="Recommendation mode" value={data.mode} />
              <ValueBlock label="Research interests" value={data.interests} />
              <ValueBlock label="Research goals" value={data.goals} />
              <ValueBlock label="Skills" value={data.skills} />
            </div>

            {data.mode.toLowerCase().includes('group') && (
              <div className="mt-6">
                <h3 className="mb-3 flex items-center gap-2 text-sm font-bold">
                  <Users className="h-4 w-4" />
                  Group members and their details
                </h3>

                {data.groupMembers.length ? (
                  <div className="grid gap-3 md:grid-cols-2">
                    {data.groupMembers.map((member, index) => {
                      const obj = asObject(member);

                      return (
                        <div
                          key={`${text(obj?.email) || text(obj?.name)}-${index}`}
                          className="rounded-xl border border-slate-200 p-4"
                        >
                          <p className="font-semibold text-slate-900">
                            {text(obj?.name) ||
                              text(obj?.full_name) ||
                              text(obj?.email) ||
                              `Group member ${index + 1}`}
                          </p>

                          <div className="mt-3 space-y-3">
                            {Object.entries(obj ?? {}).map(([key, value]) => (
                              <ValueBlock
                                key={key}
                                label={displayFieldName(key)}
                                value={value}
                              />
                            ))}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <EmptyState message="Group recommendation mode was detected, but the saved recommendation data did not expose a group-members array. The original group-creation page may store member details under a different key or structure." />
                )}
              </div>
            )}

            {!data.interests && !data.goals && !data.skills && (
              <div className="mt-4">
                <EmptyState message="Your profile fields were not found in the known browser-storage keys. We may need to connect this section to the exact keys used by your account page." />
              </div>
            )}
          </Section>

          <Section
            id="papers"
            number="02"
            title="Recommended research papers"
            description="Literature discovered through your personalized research recommendations."
            icon={<BookOpen className="h-5 w-5" />}
          >
            {data.papers.length ? (
              <div className="space-y-3">
                {data.papers.map((paper, index) => (
                  <DataCard
                    key={`${getTitle(paper, 'paper')}-${index}`}
                    item={paper}
                    index={index}
                    kind="paper"
                  />
                ))}
              </div>
            ) : (
              <EmptyState message="No recommended-paper array was found in the saved recommendation cache. This dashboard currently reads the known RESEARCHPILOT recommendation-cache keys." />
            )}
          </Section>

          <Section
            id="gaps"
            number="03"
            title="Identified research gaps"
            description="The research opportunities and limitations identified during your literature analysis."
            icon={<Search className="h-5 w-5" />}
          >
            {data.gaps.length ? (
              <div className="space-y-3">
                {data.gaps.map((gap, index) => (
                  <DataCard
                    key={`${getTitle(gap, 'gap')}-${index}`}
                    item={gap}
                    index={index}
                    kind="gap"
                  />
                ))}
              </div>
            ) : (
              <EmptyState message="No research-gap array was found. The dashboard checks the existing researchGaps and researchGapPapers session-storage entries and the known research-gap cache prefix." />
            )}
          </Section>

          <Section
            id="ideas"
            number="04"
            title="Generated project ideas"
            description="The project directions generated from your research gaps, including their supporting information."
            icon={<Lightbulb className="h-5 w-5" />}
          >
            {data.ideas.length ? (
              <div className="space-y-3">
                {data.ideas.map((idea, index) => (
                  <DataCard
                    key={`${getTitle(idea, 'idea')}-${index}`}
                    item={idea}
                    index={index}
                    kind="idea"
                  />
                ))}
              </div>
            ) : (
              <EmptyState message="No generated-project-ideas array was found in session storage. The project-ideas page may use a different storage key or nested response format." />
            )}
          </Section>

          <Section
            id="selected-project"
            number="05"
            title="Your selected project"
            description="The specific project selected for detailed planning and faculty expertise alignment."
            icon={<Target className="h-5 w-5" />}
          >
            {project ? (
              <div>
                <div className="rounded-2xl bg-slate-950 p-5 text-white sm:p-7">
                  <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-blue-300">
                    Selected research direction
                  </p>

                  <h3 className="mt-3 text-2xl font-bold tracking-tight">
                    {getTitle(project, 'Selected project')}
                  </h3>

                  {text(project.problem_statement) && (
                    <p className="mt-4 whitespace-pre-wrap text-sm leading-7 text-slate-300">
                      {text(project.problem_statement)}
                    </p>
                  )}
                </div>

                <div className="mt-4 grid gap-3 sm:grid-cols-2">
                  {Object.entries(project).map(([key, value]) => {
                    if (
                      value === null ||
                      value === undefined ||
                      value === '' ||
                      key === 'papers' ||
                      key === 'research_gaps'
                    ) {
                      return null;
                    }

                    return (
                      <ValueBlock
                        key={key}
                        label={displayFieldName(key)}
                        value={value}
                      />
                    );
                  })}
                </div>

                <Link
                  href={`/problem-statement/${text(project.idea_id)}`}
                  className="mt-5 inline-flex items-center gap-2 rounded-xl bg-slate-900 px-4 py-3 text-sm font-semibold text-white transition hover:bg-blue-700"
                >
                  View project details
                  <ExternalLink className="h-4 w-4" />
                </Link>
              </div>
            ) : (
              <EmptyState message="The selected project was not found. Open a project from Project Ideas and visit its details page first so the project can be saved for the dashboard." />
            )}
          </Section>

          <Section
            id="faculty"
            number="06"
            title="Recommended faculty"
            description="Faculty expertise aligned with your currently selected project."
            icon={<GraduationCap className="h-5 w-5" />}
          >
            {data.faculty.length ? (
              <div className="grid gap-4 lg:grid-cols-2">
                {data.faculty.map((member, index) => (
                  <FacultyCard
                    key={`${getFacultyName(member)}-${index}`}
                    member={member}
                    index={index}
                  />
                ))}
              </div>
            ) : (
              <EmptyState message="No saved faculty recommendations were found. Open the selected project's details page and wait for the faculty matches to finish loading, then return here." />
            )}
          </Section>
        </div>

        <footer className="mt-10 rounded-2xl border border-slate-200 bg-white px-5 py-6 text-center">
          <div className="mx-auto flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-blue-700">
            <CheckCircle2 className="h-5 w-5" />
          </div>

          <h2 className="mt-3 font-bold text-slate-900">
            Your research journey, consolidated
          </h2>

          <p className="mx-auto mt-2 max-w-2xl text-xs leading-6 text-slate-500">
            Review the literature, validate the research gap, refine the
            selected project, and discuss its feasibility with suitable
            faculty members.
          </p>

          <Link
            href="/project-ideas"
            className="mt-4 inline-flex items-center gap-2 rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
          >
            <ArrowLeft className="h-4 w-4" />
            Return to project ideas
          </Link>
        </footer>
      </div>

      <style jsx global>{`
        @media print {
          body {
            background: white !important;
          }

          header {
            position: static !important;
          }

          a {
            color: inherit !important;
            text-decoration: none !important;
          }

          details > summary {
            list-style: none;
          }

          .shadow-sm,
          .shadow-lg {
            box-shadow: none !important;
          }

          section,
          article {
            break-inside: avoid;
          }
        }
      `}</style>
    </main>
  );
}
